// Verify the covered Linux group after SIGKILL. Zombies have terminated and
// cannot hold pipes; reaping is their parent's duty. Other Unix ports currently
// report signal delivery only and cannot require verified group termination.
func verifyReviewProcessGroup(pid int) error {
	if runtime.GOOS != "linux" {
		return nil
	}
	deadline := time.Now().Add(time.Second)
	for {
		entries, err := os.ReadDir("/proc")
		if err != nil {
			return fmt.Errorf("process-group termination could not be observed")
		}
		if len(entries) > 100000 {
			return fmt.Errorf("process inventory exceeds coverage")
		}
		alive := false
		for _, entry := range entries {
			if _, err := strconv.Atoi(entry.Name()); err != nil {
				continue
			}
			raw, err := os.ReadFile("/proc/" + entry.Name() + "/stat")
			if processGone(err) {
				continue
			}
			if err != nil {
				return fmt.Errorf("process inventory incomplete")
			}
			end := strings.LastIndex(string(raw), ")")
			if end < 0 {
				return fmt.Errorf("process inventory malformed")
			}
			fields := strings.Fields(string(raw[end+1:]))
			if len(fields) < 3 {
				return fmt.Errorf("process inventory malformed")
			}
			group, err := strconv.Atoi(fields[2])
			if err != nil {
				return fmt.Errorf("process group malformed")
			}
			if group == pid && fields[0] != "Z" && fields[0] != "X" {
				alive = true
				break
			}
		}
		if !alive {
			return nil
		}
		if time.Now().After(deadline) {
			return fmt.Errorf("process group remained alive after termination")
		}
		time.Sleep(10 * time.Millisecond)
	}
}

// processGone reports the two ways a process exiting during the walk answers:
// the open finds no entry, or the read of an open entry finds no process.
func processGone(err error) bool {
	return errors.Is(err, os.ErrNotExist) || errors.Is(err, syscall.ESRCH)
}

// processGroupProbe keeps when the process inventory was last observed in
// full. The probe asks whether this system lets the engine observe a process
// group's termination; that does not change between two verifications of a
// closeout, and the walk reads every /proc/<pid>/stat. A success holds for
// processGroupProbeTTL; a failure is never kept (spec
// pose-review-guard-reads-the-integrity-graph-in-place).
var processGroupProbe struct {
	sync.Mutex
	ok time.Time
}

const processGroupProbeTTL = time.Minute

// processGroupVerify is the walk the probe runs; tests count it.
var processGroupVerify = verifyReviewProcessGroup

func reviewProcessGroupAvailable() error {
	processGroupProbe.Lock()
	defer processGroupProbe.Unlock()
	if !processGroupProbe.ok.IsZero() && time.Since(processGroupProbe.ok) < processGroupProbeTTL {
		return nil
	}
	if err := processGroupVerify(-1); err != nil {
		return err
	}
	processGroupProbe.ok = time.Now()
	return nil
}
